const upsertCategoryField = `-- name: UpsertCategoryField :one
INSERT INTO category_fields (category_id, label, position) VALUES ($1, $2, $3)
ON CONFLICT (category_id, label) DO UPDATE SET position = EXCLUDED.position
RETURNING id
`

type UpsertCategoryFieldParams struct {
	CategoryID int64  `json:"category_id"`
	Label      string `json:"label"`
	Position   int32  `json:"position"`
}

func (q *Queries) UpsertCategoryField(ctx context.Context, arg UpsertCategoryFieldParams) (int64, error) {
	row := q.db.QueryRow(ctx, upsertCategoryField, arg.CategoryID, arg.Label, arg.Position)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const upsertVariant = `-- name: UpsertVariant :one
INSERT INTO variants (product_id, colour_id, size_id, sku, price_kobo, compare_at_kobo, stock, active, position)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
ON CONFLICT (product_id, COALESCE(colour_id, 0), COALESCE(size_id, 0))
DO UPDATE SET sku = EXCLUDED.sku, price_kobo = EXCLUDED.price_kobo, compare_at_kobo = EXCLUDED.compare_at_kobo,
              stock = EXCLUDED.stock, active = EXCLUDED.active, position = EXCLUDED.position
RETURNING id
`

type UpsertVariantParams struct {
	ProductID     int64       `json:"product_id"`
	ColourID      pgtype.Int8 `json:"colour_id"`
	SizeID        pgtype.Int8 `json:"size_id"`
	Sku           string      `json:"sku"`
	PriceKobo     int64       `json:"price_kobo"`
	CompareAtKobo pgtype.Int8 `json:"compare_at_kobo"`
	Stock         int32       `json:"stock"`
	Active        bool        `json:"active"`
	Position      int32       `json:"position"`
}

// One row per colour + size; saving the same option again updates it.
func (q *Queries) UpsertVariant(ctx context.Context, arg UpsertVariantParams) (int64, error) {
	row := q.db.QueryRow(ctx, upsertVariant,
		arg.ProductID,
		arg.ColourID,
		arg.SizeID,
		arg.Sku,
		arg.PriceKobo,
		arg.CompareAtKobo,
		arg.Stock,
		arg.Active,
		arg.Position,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}
